const fs = require('fs');

const root = process.cwd();

function card(title, text) {
  return `<section><h3>${title}</h3><p>${text}</p></section>`;
}

function definition(term, text) {
  return `<div><dt>${term}</dt><dd>${text}</dd></div>`;
}

function faq(question, answer) {
  return `<details><summary>${question}</summary><p>${answer}</p></details>`;
}

function replaceSection(html, id, content) {
  const marker = `<section id="${id}"`;
  const start = html.indexOf(marker);
  if (start === -1) throw new Error(`Missing section ${id}`);
  const tagEnd = html.indexOf('>', start);
  const tags = /<\/?section\b[^>]*>/gi;
  let depth = 1;
  tags.lastIndex = tagEnd + 1;
  while (depth > 0) {
    const match = tags.exec(html);
    if (!match) throw new Error(`Unclosed section ${id}`);
    depth += match[0].startsWith('</') ? -1 : 1;
    if (depth === 0) return html.slice(0, start) + content + html.slice(match.index + match[0].length);
  }
  return html;
}

function buildPage(config) {
  let html = fs.readFileSync(config.file, 'utf8');
  const content = {
    'what-is': `<section id="what-is"><h2>What Is ${config.topic}?</h2>${config.intro.map((paragraph) => `<p>${paragraph}</p>`).join('')}</section>`,
    importance: `<section id="importance"><h2>Why Is ${config.topic} Important in Engineering?</h2>${config.importance.map((paragraph) => `<p>${paragraph}</p>`).join('')}<div class="article-callout article-callout--note"><strong>Use a declared operating basis.</strong><span>${config.basisNote}</span></div></section>`,
    terms: `<section id="terms"><h2>Key Terms and Definitions</h2><dl class="definition-list">${config.terms.map(([term, text]) => definition(term, text)).join('')}</dl></section>`,
    principle: `<section id="principle"><h2>Fundamental Principle</h2>${config.principle.map((paragraph) => `<p>${paragraph}</p>`).join('')}</section>`,
    formulae: `<section id="formulae"><h2>Formulae, Symbols and Units</h2><div class="formula-grid">${config.formulas.map(([title, equation, text]) => `<section class="formula-card"><h3>${title}</h3><p class="formula-card__equation">${equation}</p><p>${text}</p></section>`).join('')}</div><div class="article-callout article-callout--note"><strong>Unit consistency is part of the calculation.</strong><span>${config.unitNote}</span></div><h3>Interpretation before use</h3><p>${config.interpretation}</p><p>${config.escalation}</p></section>`,
    assumptions: `<section id="assumptions"><h2>Assumptions and Validity Range</h2><ul>${config.assumptions.map((item) => `<li>${item}</li>`).join('')}</ul></section>`,
    factors: `<section id="factors"><h2>Factors Affecting the Result</h2><div class="article-card-grid">${config.factors.map(([title, text]) => card(title, text)).join('')}</div><figure class="article-figure"><img src="${config.visual.path}" alt="${config.visual.alt}"><figcaption>${config.visual.caption}</figcaption></figure></section>`,
    method: `<section id="method"><h2>Step-by-Step Engineering Method</h2><ol class="method-list">${config.method.map((item) => `<li>${item}</li>`).join('')}</ol><h3>What to record with the result</h3><p>${config.recording}</p><p>${config.reviewFocus}</p></section>`,
    example: `<section id="example"><h2>Illustrative Engineering Example</h2><div class="example-card"><p class="portal-kicker">Hypothetical preliminary example — not a design calculation</p>${config.example.map((paragraph) => `<p>${paragraph}</p>`).join('')}</div></section>`,
    applications: `<section id="applications"><h2>Industrial Applications</h2><div class="article-card-grid">${config.applications.map(([title, text]) => card(title, text)).join('')}</div></section>`,
    mistakes: `<section id="mistakes"><h2>Common Mistakes and Limitations</h2><div class="article-callout article-callout--warning"><strong>Do not extend a preliminary relation beyond its basis.</strong><span>${config.limitNote}</span></div><ul>${config.mistakes.map((item) => `<li>${item}</li>`).join('')}</ul></section>`,
    faq: `<section id="faq"><h2>Frequently Asked Questions</h2><div class="faq-list">${config.faqs.map(([question, answer]) => faq(question, answer)).join('')}</div></section>`,
    references: `<section id="references"><h2>References</h2><ol class="references-list">${config.references.map((reference) => `<li>${reference}</li>`).join('')}</ol><p class="references-note">This page is an original educational summary. It does not reproduce protected book text, figures, tables or standards material. Use current approved sources and the project design basis for final work.</p></section>`,
    review: `<section id="review"><h2>Review Information</h2><h3>Evidence expected before design use</h3><p>This ${config.topic} guide explains the calculation and decision framework, but it is not a substitute for the project design record. Before using a result beyond a preliminary study, verify the actual equipment or line configuration, operating range, material or fluid condition, drawings, measurement basis and governing project requirements.</p><p>Retain the input source, calculation version, units, condition basis, assumptions, limits and reviewer comments with the result. Recalculate when a flow, temperature, pressure, geometry, equipment curve, control setting or system line-up changes; an earlier valid result may not remain valid after a plant modification.</p><p>Where reliability, safety, environmental compliance, production capacity or a supplier guarantee is affected, compare the result against current manufacturer information, applicable codes and qualified engineering review before making a final decision. This requirement remains important even when a simple worked example appears to match the expected duty. Record curve tolerances, safety margins and revisions as well.</p><div class="review-panel"><strong>Expanded content review completed: 30 August 2026.</strong><span>Content type: ${config.contentType}. The review checks topic scope, declared basis, source listing, relevant internal links and limits of use. Independent qualified-engineer review remains required before final design, procurement, operation or safety use.</span></div></section>`,
  };

  Object.entries(content).forEach(([id, section]) => { html = replaceSection(html, id, section); });
  html = html.replace('style.css?v=20260830-final-knowledge', 'style.css?v=20260830-fluid-depth');
  fs.writeFileSync(config.file, html, 'utf8');
}

